  (6, 40, 'Stage 3 investigation: planning', 'Stage 3 investigation: presenting', 'Stage 3 skills check', 'Reflection and celebration')
),
l(n) AS (VALUES (1), (2), (3), (4)),
x AS (
  SELECT
    w.y AS y, w.wk AS wk, u.n AS un, (w.wk - u.wf + 1) AS uw, (u.wt - u.wf + 1) AS uweeks,
    u.unit AS unit, u.strand AS strand, l.n AS ln,
    CASE l.n WHEN 1 THEN w.t1 WHEN 2 THEN w.t2 WHEN 3 THEN w.t3 ELSE w.t4 END AS tt,
    's3-mat-y' || w.y || '-w' || printf('%02d', w.wk) || '-l' || l.n AS k
  FROM w
  JOIN u ON u.y = w.y AND w.wk BETWEEN u.wf AND u.wt
  CROSS JOIN l
)
INSERT OR IGNORE INTO lessons (id, family_id, seed_key, title, stage, learning_area, unit_id, status, data, created_at, updated_at)
SELECT
  'seed-' || k, NULL, k,
  'Year ' || y || ', Week ' || wk || ', Lesson ' || ln || ': ' || tt,
  'S3', 'Mathematics', NULL, 'approved',
  json_object(
    'year_level', 'Year ' || y,
    'subject', strand,
    'unit_title', unit,
    'unit_number', un,
    'week', wk,
    'week_in_unit', uw,
    'lesson_number', ln,
    'lesson_role', CASE ln WHEN 1 THEN 'Concept' WHEN 2 THEN 'Strategies' WHEN 3 THEN 'Problem solving' ELSE 'Fluency and review' END,
    'learning_intention',
      CASE ln
        WHEN 1 THEN 'Concept lesson in the unit ' || unit || '. Focus: ' || tt || '. Children learn the big idea through explicit teaching, worked examples and models.'
        WHEN 2 THEN 'Strategies lesson in the unit ' || unit || '. Focus: ' || tt || '. Children practise efficient strategies with guided practice and clear worked examples.'
        WHEN 3 THEN 'Problem solving lesson in the unit ' || unit || '. Focus: ' || tt || '. Children apply the week''s ideas to problems and explain their reasoning.'
        ELSE 'Fluency and review lesson in the unit ' || unit || '. Focus: ' || tt || '. Children build speed and accuracy and check their understanding.'
      END || CASE WHEN uw = uweeks THEN ' This is the review and consolidation week for the unit.' ELSE '' END,
    'outcome_codes', json('[]'),
    'coming_soon', json('true'),
    'source_note', 'Coming soon. This is a planned lesson card. Outcome codes are not assigned yet: map this lesson to the NESA Mathematics K-6 Stage 3 syllabus before it is built.'
  ),
  '2026-10-11T01:00:00Z', '2026-10-11T01:00:00Z'
FROM x;
